query:
query Partitions($assetKey: AssetKeyInput!) { assetNodeOrError(assetKey: $assetKey) { __typename ... on AssetNode { partitionKeys partitionKeysByDimension { name partitionKeys } assetPartitionStatuses { 
  __typename
  ... on DefaultPartitionStatuses { materializedPartitions failedPartitions materializingPartitions }
  ... on TimePartitionStatuses { ranges { startKey endKey status } }
 ... on MultiPartitionStatuses { primaryDimensionName ranges { primaryDimStartKey primaryDimEndKey secondaryDim { 
  __typename
  ... on DefaultPartitionStatuses { materializedPartitions failedPartitions materializingPartitions }
  ... on TimePartitionStatuses { ranges { startKey endKey status } }
 } } } } } ... on AssetNotFoundError { message } } }
